import re,glob,json
runs={}
order=[]
for f in sorted(glob.glob('logs/sched/*.log')):
    for l in open(f):
        m=re.match(r'(\S+) (start|end) (\S+) run=(\S+) (.*)',l.strip())
        if not m: continue
        ts,k,job,rid,rest=m.groups()
        if k=='start':
            runs[rid]=dict(id=rid,job=job,start=ts,ver=re.search(r'version=(\S+)',rest).group(1),loaded=re.search(r'loaded=(\S+)',rest).group(1))
            fm=re.search(r'feed=(\S+)',rest)
            if fm: runs[rid]['feed']=fm.group(1)
            order.append(rid)
        else:
            runs[rid]['end']=ts; runs[rid]['wrote']=re.search(r'wrote=(\S+)',rest).group(1)
new=[runs[r] for r in order if runs[r]['ver']=='4.2.0']
print(len(new), new[0])
json.dump(new,open('/tmp/runs.json','w'))
E

