cd /app; cat > /tmp/aud2.py <<'E'
import re,json,glob,sys
d=sys.argv[1]
res={}
for f in sorted(glob.glob('/app/logs/audit/*.txt')):
    L=open(f).read().splitlines()
    snap=L[1].split()[1]
    act=json.load(open('/app/var/snapshots/'+snap))
    st=json.load(open(glob.glob(f'{d}/var/snapshots/{snap[:6]}-*')[0]))
    books={}
    for sec in('docks','members'):
        for k,v in act[sec].items():
            for kk,vv in v.items():
                if isinstance(vv,int) and kk!='capacity': books[f'{sec}.{k}.{kk}']=vv
    hb={h:True for h in act['holds']}
    for l in L:
        m=re.match(r'mismatch (\S+) state=(\S+) books=(\S+)',l)
        if m and not m[1].startswith('holds'): books[m[1]]=int(m[3])
        if m and m[1].startswith('holds') and m[3]=='absent': hb.pop(m[1].split('.')[1])
    diff={}
    for k,b in books.items():
        s,*p=k.split('.')
        cur=st[s][p[0]][p[1]]
        diff[k]=cur-b
    res[f[-20:]]=(diff,set(st['holds']),set(hb))
ks=list(res)
for k in res[ks[0]][0]:
    v=[res[x][0][k] for x in ks]
    if len(set(v))>1: print(k,v)
for x in ks: print(x,'holds extra',res[x][1]^res[x][2])
E
